#include <cstddef>
#include <iostream>
#include <new>

struct Token { int value; };

int main() {
  alignas(Token) std::byte storage[sizeof(Token)];
  Token* first = new (storage) Token{1};
  first->~Token();
  Token* second = new (storage) Token{2};
  std::cout << second->value;
  second->~Token();
}
